4	/**
5	 * Marketing layout primitives (v2 redesign) — the single reuse layer every page
6	 * is built from, so the whole site reads as one designed thing.
7	 *
8	 *  - <Section>   full-width band with an alternating background "tone" and a
9	 *                consistent vertical rhythm + content rail. Replaces the ad-hoc
10	 *                `mx-auto max-w-6xl px-5 py-20` strings copy-pasted everywhere.
11	 *  - <PageHero>  the standard sub-page hero (eyebrow → title → sub → CTAs +
12	 *                optional visual). Replaces ~10 hand-rolled hero blocks.
13	 *  - <Eyebrow>   the uppercase tag above a heading.
14	 *  - <SectionTitle> heading + optional sub, centered or left.
15	 *
16	 * Colors and animations are the existing brand system (navy + violet/blue).
17	 */
18	
19	type Tone = "base" | "panel" | "deep" | "light";
20	type Size = "sm" | "md" | "lg";
21	
22	const TONE: Record<Tone, string> = {
23	  base: "",
24	  panel: "tone-panel",
25	  deep: "tone-deep",
26	  light: "tone-light",
27	};
28	const PAD: Record<Size, string> = {
29	  sm: "py-14 sm:py-16",
30	  md: "py-20 sm:py-24",
31	  lg: "py-24 sm:py-32",
32	};
33	
34	/** A full-width section band. `tone` alternates the background for rhythm. */
35	export function Section({
36	  children,
37	  tone = "base",
38	  size = "md",
39	  id,
40	  className = "",
41	}: {
42	  children: React.ReactNode;
43	  tone?: Tone;
44	  size?: Size;
45	  id?: string;
46	  className?: string;
47	}) {
48	  return (
49	    <section id={id} className={`relative ${TONE[tone]} ${PAD[size]} ${className}`}>
50	      <div className="rail">{children}</div>
51	    </section>
52	  );
53	}
54	
55	/** Uppercase eyebrow tag. `pill` gives it the bordered chip treatment. */
56	export function Eyebrow({ children, pill = false }: { children: React.ReactNode; pill?: boolean }) {
57	  return <span className={pill ? "eyebrow-pill" : "eyebrow"}>{children}</span>;
58	}
59	
60	/** Section heading block: eyebrow + title + optional sub. */
61	export function SectionTitle({
62	  eyebrow,
63	  title,
64	  sub,
65	  align = "center",
66	  className = "",
67	}: {
68	  eyebrow?: string;
69	  title: React.ReactNode;
70	  sub?: React.ReactNode;
71	  align?: "center" | "left";
72	  className?: string;
73	}) {
74	  const alignCls = align === "center" ? "mx-auto text-center" : "text-left";
75	  return (
76	    <div className={`max-w-2xl ${alignCls} ${className}`}>
77	      {eyebrow && <Eyebrow>{eyebrow}</Eyebrow>}
78	      <h2 className="mt-3 text-3xl font-bold tracking-tight text-[var(--fg)] sm:text-4xl text-balance">{title}</h2>
79	      {sub && <p className="mt-4 text-lg leading-relaxed text-[var(--fg-muted)]">{sub}</p>}
80	    </div>
81	  );
82	}
