143	                  </Link>
144	                )}
145	              </div>
146	            )}
147	            {children}
148	          </Reveal>
149	          {visual && <Reveal className="lg:pl-6">{visual}</Reveal>}
150	        </div>
151	      </div>
152	    </section>
153	  );
154	}
