type CtaLink = { label: string; href: string };

/**
 * The site-wide closing CTA band. Parameterized so bespoke pages reuse the exact
 * same glass/aura treatment instead of forking their own copy of it — pass
 * `title`/`sub`/`primary`/`secondary`/`note` to override, or render `<CtaBand />`
 * for the default deploy-your-server promise. Defaults keep every existing
 * caller (business-email, nxcloud, …) byte-for-byte unchanged.
 */
export function CtaBand({
  title,
  sub,
  primary,
  secondary,
  note,
}: {
  title?: React.ReactNode;
  sub?: React.ReactNode;
  primary?: CtaLink;
  secondary?: CtaLink;
  note?: React.ReactNode;
} = {}) {
  // The default band renders on many pages, so its promise is the one prospects
  // meet most. It once read "No credit card required to get started. Spin up a
  // VPS, break things, and only pay for what you keep running." — none of which
  // survives contact with the product: free deploys are admin-only
  // (`formData.get("free") === "1" && isAdmin`), a customer with no balance gets
  // "Insufficient balance. Top up your wallet first.", and a term is paid up
  // front rather than metered on what you keep running. What is true is that the
  // ACCOUNT is free and takes no card. Say that, and say plainly where the money
  // starts.
  const heading = title ?? (
    <>
      Deploy your first server in <span className="grad-text">under a minute</span>
    </>
  );
  const subCopy =
    sub ??
    "Creating an account is free and takes no card details. You pay when you deploy — choose a billing term and pay from your wallet or by card at checkout.";
  const primaryCta = primary ?? { label: "Create your account", href: "/register" };
  const secondaryCta = secondary ?? { label: "Compare plans", href: "/pricing" };

  return (
    <Reveal className="relative overflow-hidden rounded-3xl border border-white/[0.08] bg-navy-850/70 px-8 py-16 text-center backdrop-blur-md sm:px-16">
      <div
        className="pointer-events-none absolute inset-0 opacity-70"
        style={{
          backgroundImage:
            "radial-gradient(ellipse 60% 60% at 30% 0%, rgba(59,130,246,0.18), transparent), radial-gradient(ellipse 50% 60% at 80% 100%, rgba(138,112,251,0.18), transparent)",
        }}
      />
      <div className="relative">
        <h2 className="mx-auto max-w-2xl text-3xl font-bold tracking-tight sm:text-4xl">{heading}</h2>
        <p className="mx-auto mt-4 max-w-xl text-lg text-slate-400">{subCopy}</p>
        <div className="mt-8 flex flex-wrap items-center justify-center gap-3">
          <Link href={primaryCta.href} className="btn-primary px-6 py-3 text-base">
            {primaryCta.label}
            <IconArrow size={16} />
          </Link>
          <Link href={secondaryCta.href} className="btn-secondary px-6 py-3 text-base">
            {secondaryCta.label}
          </Link>
        </div>
        {note && <p className="mt-5 text-sm text-slate-500">{note}</p>}
      </div>
    </Reveal>
  );
}

{/* Final CTA */}
<Section tone="deep" size="lg">
  <CtaBand
    title={
      <>
        Open six consoles and <span className="grad-text">start shipping</span>
      </>
    }
    sub="Creating an account is free and takes no card. Deploy a Nxeon VPS, open Matrix, and build your first app in minutes — with your own API key or your Claude subscription."
    primary={{ label: "Start building — create a free account", href: "/register" }}
    secondary={{ label: "Open Matrix", href: "/dashboard/build" }}
    note="Runs on your own VPS · Your key or your subscription · You own everything you build"
  />
</Section>

{/* ── Final CTA ────────────────────────────────────────────────────── */}
<Section tone="deep" size="lg">
  <CtaBand
    title={
      <>
        Stop putting off the move. <span className="grad-text">Bring it all over in one click.</span>
      </>
    }
    sub="Migration is free and your old server keeps running the whole time. Connect it, scan it, and see your whole stack come up on Nxeon — with nothing to lose."
    primary={{ label: "Migrate free", href: "/dashboard/migrate" }}
    secondary={{ label: "Create an account", href: "/register" }}
  />
</Section>

